package com.example.agendapersonal.respaldo;

import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.content.ContentValues;
import androidx.test.ext.junit.runners.AndroidJUnit4;import com.example.agendapersonal.data.DatabaseHelper;
import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;

/** Solo bases :memory:. No accede a sesiones, archivos ni registros de la instalación. */
@RunWith(AndroidJUnit4.class)
public class GestorRespaldoInstrumentedTest {
    SQLiteDatabase fuente,destino;
    @Before public void crear(){fuente=base();destino=base();}
    SQLiteDatabase base(){SQLiteDatabase db=SQLiteDatabase.create(null);db.setForeignKeyConstraintsEnabled(true);for(String sql:DatabaseHelper.esquemaTablasRespaldo())db.execSQL(sql);db.setVersion(2);return db;}
    @After public void cerrar(){fuente.close();destino.close();}
    void tarea(SQLiteDatabase db,String id,String descripcion){db.execSQL("INSERT INTO tareas(id,descripcion,fecha_vencimiento,categoria,prioridad) VALUES (?,?,?,'FREELANCE','ALTA')",new Object[]{id,descripcion,"2026-11-05"});}
    long cantidad(SQLiteDatabase db,String tabla){try(Cursor c=db.rawQuery("SELECT count(*) FROM "+EsquemaRespaldo.nombre(tabla),null)){c.moveToFirst();return c.getLong(0);}}
    String texto(SQLiteDatabase db,String sql){try(Cursor c=db.rawQuery(sql,null)){assertTrue(c.moveToFirst());return c.getString(0);}}
    void restaurar()throws Exception {destino.beginTransaction();try{GestorRespaldo.reemplazarTablas(destino,fuente);destino.setTransactionSuccessful();}finally{destino.endTransaction();}}
    @Test public void reemplazaSinDuplicarYPreservaRelacionesYTombstones()throws Exception {
        tarea(destino,"vieja","Estado previo");fuente.execSQL("INSERT INTO personas(id,nombre) VALUES ('persona','Ángela')");fuente.execSQL("INSERT INTO direcciones(id,persona_id,calle,numero,localidad,provincia) VALUES ('direccion','persona','Calle','12','Ciudad','Provincia')");tarea(fuente,"nueva","Revisión\ncon acentos: ñ");fuente.execSQL("UPDATE tareas SET deleted_at='2026-11-05T12:00:00Z',revision=2,observaciones=NULL WHERE id='nueva'");restaurar();restaurar();assertEquals(1,cantidad(destino,"tareas"));assertEquals("Revisión\ncon acentos: ñ",texto(destino,"SELECT descripcion FROM tareas"));assertEquals("persona",texto(destino,"SELECT persona_id FROM direcciones"));assertNotNull(texto(destino,"SELECT deleted_at FROM tareas"));try(Cursor c=destino.rawQuery("SELECT observaciones,revision FROM tareas",null)){assertTrue(c.moveToFirst());assertTrue(c.isNull(0));assertEquals(2,c.getInt(1));}GestorRespaldo.integridad(destino);
    }
    @Test public void fkInvalidaRevierteLosDatosActuales()throws Exception {tarea(destino,"conservar","No perder");fuente.setForeignKeyConstraintsEnabled(false);fuente.execSQL("INSERT INTO direcciones(id,persona_id,calle,numero,localidad,provincia) VALUES ('huerfana','inexistente','Calle','1','Ciudad','Provincia')");try{restaurar();fail();}catch(android.database.sqlite.SQLiteConstraintException esperado){}assertEquals("No perder",texto(destino,"SELECT descripcion FROM tareas"));assertEquals(0,cantidad(destino,"direcciones"));}
    @Test public void interrupcionAntesDelCommitRevierteTodo()throws Exception {tarea(destino,"conservar","Versión anterior");tarea(fuente,"recuperar","Versión de la copia");destino.beginTransaction();try{GestorRespaldo.reemplazarTablas(destino,fuente);throw new java.io.IOException("Interrupción simulada");}catch(java.io.IOException esperado){}finally{destino.endTransaction();}assertEquals("Versión anterior",texto(destino,"SELECT descripcion FROM tareas"));}
    @Test public void rechazaEstructuraDesconocidaSinModificarDestino()throws Exception {tarea(destino,"conservar","No tocar");fuente.execSQL("CREATE VIEW futura AS SELECT * FROM tareas");try{restaurar();fail();}catch(java.io.IOException esperado){}assertEquals("No tocar",texto(destino,"SELECT descripcion FROM tareas"));}
    @Test public void conservaHistorialOrigenYConflictos()throws Exception {for(String t:new String[]{"historico_archivo","sync_conflicts","sync_outbox_sent","eventos_ocurrencias"})fuente.execSQL(EsquemaRespaldo.tablas().get(t));fuente.execSQL("INSERT INTO historico_archivo VALUES ('sha','Hoja',12,'{\"Cantidad\":5}', 'Revisar')");fuente.execSQL("INSERT INTO sync_conflicts(owner_id,change_id,entity_type,entity_id,local_payload,remote_change,created_at) VALUES ('cuenta','cambio','tareas','tarea','{\"local\":1}','{\"remota\":2}','2026-11-05T12:00:00Z')");fuente.execSQL("INSERT INTO sync_outbox_sent VALUES ('cuenta','cambio','2026-11-05T12:00:00Z')");fuente.execSQL("INSERT INTO eventos_ocurrencias VALUES ('evento','serie',3,'2026-11-05')");restaurar();assertEquals("{\"Cantidad\":5}",texto(destino,"SELECT original_json FROM historico_archivo"));assertEquals("{\"local\":1}",texto(destino,"SELECT local_payload FROM sync_conflicts"));assertEquals(1,cantidad(destino,"sync_outbox_sent"));assertEquals("serie",texto(destino,"SELECT serie_id FROM eventos_ocurrencias"));}
    @Test public void limpiaExcepcionesLocalesAusentesEnLaCopia()throws Exception {destino.execSQL(EsquemaRespaldo.tablas().get("eventos_ocurrencias"));destino.execSQL("INSERT INTO eventos_ocurrencias VALUES ('evento','serie',4,'2026-11-05')");restaurar();assertEquals(0,cantidad(destino,"eventos_ocurrencias"));}
    @Test public void snapshotCompletoBajoTransaccionNoAbreOtraConexion()throws Exception {android.content.Context c=new com.example.agendapersonal.ContextoPrueba(androidx.test.platform.app.InstrumentationRegistry.getInstrumentation().getTargetContext(),"test_snapshot_"+java.util.UUID.randomUUID()+"_");java.io.File dir=new java.io.File(c.getCacheDir(),"test_snapshot_"+java.util.UUID.randomUUID());assertTrue(dir.mkdirs());tarea(fuente,"copia","Texto preservado");try{fuente.beginTransaction();try{org.json.JSONObject manifest=GestorRespaldo.snapshot(c,fuente,dir);assertEquals(1,manifest.getJSONObject("filas").getLong("tareas"));assertEquals(ArchivoRespaldo.sha256(new java.io.File(dir,"agenda.db")),manifest.getString("sha256"));fuente.setTransactionSuccessful();}finally{fuente.endTransaction();}try(SQLiteDatabase copia=SQLiteDatabase.openDatabase(new java.io.File(dir,"agenda.db").getAbsolutePath(),null,SQLiteDatabase.OPEN_READONLY)){assertEquals("Texto preservado",texto(copia,"SELECT descripcion FROM tareas"));GestorRespaldo.integridad(copia);}}finally{for(java.io.File f:dir.listFiles())f.delete();dir.delete();}}
}
